async (page) => {
  const fs = require('fs');
  const path = require('path');
  const root = '/tmp/mcp-workspace';
  const emails = new Set();
  // Email regex - RFC-ish, conservative
  const re = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
  function walk(dir) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const e of entries) {
      const p = path.join(dir, e.name);
      if (e.isDirectory()) walk(p);
      else if (e.isFile()) {
        try {
          const content = fs.readFileSync(p, 'utf8');
          const matches = content.match(re);
          if (matches) matches.forEach(m => emails.add(m));
        } catch(_) {}
      }
    }
  }
  walk(root);
  // Remove unique_emails.txt if any prior content matched (we want fresh extraction excluding the output file itself)
  const list = [...emails].sort((a,b) => a.toLowerCase().localeCompare(b.toLowerCase()));
  return { count: list.length, emails: list };
}

